.admin-table-container {
    background: var\(--white\);
    border: 1px solid var\(--sand\);
    border-radius: 8px;
    overflow-x: auto;
    margin-bottom: 2rem;
}

.admin-table {
    width: 100%;
    border-collapse: collapse;
}

.admin-table thead {
    background: var\(--cream\);
    border-bottom: 2px solid var\(--sand\);
}

.admin-table th {
    padding: 1rem;
    text-align: left;
    font-weight: 600;
    color: var\(--braai-coal\);
    white-space: nowrap;
}

.admin-table td {
    padding: 1rem;
    border-bottom: 1px solid var\(--sand\);
}

.admin-table tbody tr:hover {
    background: var\(--cream\);
}

.table-image {
    width: 60px;
    height: 60px;
    object-fit: cover;
    border-radius: 4px;
}

.table-image-placeholder {
    width: 60px;
    height: 60px;
    background: var\(--sand\);
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
    font-size: 0.7rem;
    color: var\(--text-secondary\);
}

.badge {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background: var\(--sand\);
    color: var\(--braai-coal\);
    border-radius: 12px;
    font-size: 0.85rem;
    font-weight: 600;
}

.status-badge {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    border-radius: 12px;
    font-size: 0.85rem;
    font-weight: 600;
}

.status-success {
    background: rgba\(0, 122, 77, 0.1\);
    color: var\(--sa-green\);
}

.status-danger {
    background: rgba\(216, 67, 21, 0.1\);
    color: var\(--braai-fire\);
}

.action-cell {
    white-space: nowrap;
}

.btn-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: 1px solid var\(--sand\);
    background: var\(--white\);
    border-radius: 4px;
