}

.form-actions {
    display: flex;
    gap: 1rem;
    margin-top: 2rem;
}

/* Responsive Admin Styles */
@media \(max-width: 768px\) {
    .admin-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }

    .admin-actions {
        width: 100%;
        flex-wrap: wrap;
